@testable import ConetChatSDK
import XCTest

/// Own route vs chain. Fixtures: route458 is the public route key of mailbox
/// node B6FF020087998A06 (#458, read from AddressPGP); routeOther is a made-up
/// key standing in for the stray mailbox (#234) of the RC3 Samsung run.
final class OwnRouteCheckTests: XCTestCase {
	func testRouteKeyIdIsTheEncryptionSubkeyIdLikeTheChainRecord() {
		XCTAssertEqual(BeamioOwnRouteCheck.routeKeyId(Self.route458), "B6FF020087998A06")
		XCTAssertEqual(BeamioOwnRouteCheck.routeKeyId(Self.routeOther), "F7FD9A642E5B8E42")
		XCTAssertEqual(BeamioOwnRouteCheck.routeKeyId(Self.route458.replacingOccurrences(of: "\n", with: "\r\n")), "B6FF020087998A06")
		XCTAssertEqual(BeamioOwnRouteCheck.routeKeyId("not armor"), "")
	}

	func testSearchKeyCallDataHasTheRightSelector() {
		XCTAssertEqual(
			BeamioOwnRouteCheck.searchKeyCallData(eoa: "0xABCDEFabcdefABCDEFabcdefABCDEFabcdefABCD"),
			"0x052f2778000000000000000000000000abcdefabcdefabcdefabcdefabcdefabcdefabcd"
		)
		XCTAssertNil(BeamioOwnRouteCheck.searchKeyCallData(eoa: "0x12"))
	}

	func testDecodesTheSearchKeyReply() {
		XCTAssertEqual(
			BeamioOwnRouteCheck.decodeSearchKeyResult(Self.replyOk),
			.ok(routeKeyId: "B6FF020087998A06", routeArmor: Self.route458)
		)
		XCTAssertEqual(BeamioOwnRouteCheck.decodeSearchKeyResult(Self.replyEmpty), .empty)
		XCTAssertEqual(BeamioOwnRouteCheck.decodeSearchKeyResult("0x"), .error("empty_reply"))
		XCTAssertEqual(BeamioOwnRouteCheck.decodeSearchKeyResult("0x1234"), .error("short_reply"))
	}

	func testVerdicts() {
		let chain458 = BeamioOwnRouteCheck.ChainRoute.ok(routeKeyId: "B6FF020087998A06", routeArmor: Self.route458)
		XCTAssertEqual(BeamioOwnRouteCheck.verdict(listenArmor: Self.route458, chain: chain458), .match)
		XCTAssertEqual(
			BeamioOwnRouteCheck.verdict(listenArmor: Self.routeOther, chain: chain458),
			.switchTo(routeKeyId: "B6FF020087998A06", routeArmor: Self.route458)
		)
		XCTAssertEqual(BeamioOwnRouteCheck.verdict(listenArmor: Self.route458, chain: .empty), .noRoute)
		XCTAssertEqual(BeamioOwnRouteCheck.verdict(listenArmor: Self.routeOther, chain: .error("x")), .retry("x"))
	}

	/// Airplane mode: reads fail, the route is kept; back online the listen ends on the chain mailbox.
	func testAirplaneModeThenOnlineEndsOnTheChainMailbox() {
		var listenRoute = Self.routeOther
		var reads: [BeamioOwnRouteCheck.ChainRoute] = [
			.error("NSURLErrorDomain:-1009"),
			.error("timeout"),
			.ok(routeKeyId: "B6FF020087998A06", routeArmor: Self.route458),
		]
		var waits: [TimeInterval] = []
		var routesWhileOffline: [String] = []
		let v = BeamioOwnRouteCheck.reconcile(
			listenArmor: { listenRoute },
			read: { reads.removeFirst() },
			sleep: { s in waits.append(s); routesWhileOffline.append(listenRoute); return true }
		)
		XCTAssertEqual(waits, [5, 15])
		XCTAssertTrue(routesWhileOffline.allSatisfy { $0 == Self.routeOther })
		guard case .switchTo(_, let armor) = v else { return XCTFail("expected a switch, got \(v)") }
		listenRoute = armor
		XCTAssertEqual(BeamioOwnRouteCheck.routeKeyId(listenRoute), "B6FF020087998A06")
		XCTAssertEqual(
			BeamioOwnRouteCheck.reconcile(listenArmor: { listenRoute }, read: { .ok(routeKeyId: "B6FF020087998A06", routeArmor: Self.route458) }, sleep: { _ in true }),
			.match
		)
	}

	func testAGoneSessionStopsRetrying() {
		var reads = 0
		let v = BeamioOwnRouteCheck.reconcile(listenArmor: { Self.route458 }, read: { reads += 1; return .error("x") }, sleep: { _ in false })
		XCTAssertEqual(v, .retry("x"))
		XCTAssertEqual(reads, 1)
	}

	func testBackoffCapsAtTheLastDelay() {
		var waits: [TimeInterval] = []
		_ = BeamioOwnRouteCheck.reconcile(listenArmor: { Self.route458 }, read: { .error("x") }, sleep: { s in waits.append(s); return waits.count < 9 })
		XCTAssertEqual(waits, [5, 15, 30, 60, 120, 300, 300, 300, 300])
	}

